<?php
require __DIR__.'/../app/bootstrap.php';require_permission('cities.manage');$msg=$err=null;
if($_SERVER['REQUEST_METHOD']==='POST'){try{csrf_check();$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$slug=trim($_POST['slug']??'');if(!$name||!$slug)throw new RuntimeException('Name and slug required.');$status=isset($_POST['status'])?1:0;if($id)db()->prepare("UPDATE cities SET name=?,slug=?,status=? WHERE id=?")->execute([$name,$slug,$status,$id]);else{db()->prepare("INSERT INTO cities(name,slug,status) VALUES(?,?,?)")->execute([$name,$slug,$status]);$id=(int)db()->lastInsertId();}db()->prepare("INSERT INTO city_details(city_id,province,district,latitude,longitude,map_url,timezone,description) VALUES(?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE province=VALUES(province),district=VALUES(district),latitude=VALUES(latitude),longitude=VALUES(longitude),map_url=VALUES(map_url),timezone=VALUES(timezone),description=VALUES(description)")->execute([$id,trim($_POST['province']??'')?:null,trim($_POST['district']??'')?:null,trim($_POST['latitude']??'')?:null,trim($_POST['longitude']??'')?:null,trim($_POST['map_url']??'')?:null,trim($_POST['timezone']??'Asia/Karachi'),trim($_POST['description']??'')?:null]);$msg='City saved.';}catch(Throwable $e){$err=$e->getMessage();}}
$edit=null;if(isset($_GET['edit'])){$q=db()->prepare("SELECT c.*,cd.* FROM cities c LEFT JOIN city_details cd ON cd.city_id=c.id WHERE c.id=?");$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
$q=db()->query("SELECT c.*,cd.province,cd.district,cd.latitude,cd.longitude,(SELECT COUNT(*) FROM businesses b WHERE b.city_id=c.id) business_count FROM cities c LEFT JOIN city_details cd ON cd.city_id=c.id ORDER BY c.name");$rows=$q->fetchAll();require __DIR__.'/../app/layout.php';page_start('Cities',true);
?>
<div class="admin-page-hero"><h2>Cities & Location</h2><p>Add cities with province, district, map coordinates and browser geolocation.</p></div><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="error"><?=e($err)?></div><?php endif;?>
<div class="admin-split"><div class="card"><h3><?=$edit?'Edit City':'Add City'?></h3><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e($edit['id']??0)?>"><div class="admin-form-grid"><div class="full"><label>Name</label><input class="input" name="name" value="<?=e($edit['name']??'')?>" required></div><div class="full"><label>Slug</label><input class="input" name="slug" value="<?=e($edit['slug']??'')?>" required></div><div><label>Province</label><input class="input" name="province" value="<?=e($edit['province']??'Punjab')?>"></div><div><label>District</label><input class="input" name="district" value="<?=e($edit['district']??'')?>"></div><div><label>Latitude</label><input class="input" id="lat" name="latitude" value="<?=e($edit['latitude']??'')?>"></div><div><label>Longitude</label><input class="input" id="lng" name="longitude" value="<?=e($edit['longitude']??'')?>"></div><?php if(setting_bool('browser_geolocation_enabled',true)):?><div class="full geo-box"><button class="btn ghost" type="button" onclick="geo()">⌖ Use Current Location</button><span class="muted" id="geoStatus"> Browser permission required.</span></div><?php endif;?><div class="full"><label>Map URL</label><input class="input" name="map_url" value="<?=e($edit['map_url']??'')?>"></div><div><label>Timezone</label><input class="input" name="timezone" value="<?=e($edit['timezone']??'Asia/Karachi')?>"></div><div><label><input type="checkbox" name="status" <?=($edit['status']??1)?'checked':''?>> Active</label></div><div class="full"><label>Description</label><textarea class="input" rows="3" name="description"><?=e($edit['description']??'')?></textarea></div></div><br><button class="btn">Save City</button></form></div>
<div class="card"><table><tr><th>City</th><th>Location</th><th>Businesses</th><th>Status</th><th></th></tr><?php foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong><br><span class="muted"><?=e($r['slug'])?></span></td><td><?=e(($r['district']?:'—').' · '.($r['province']?:'—'))?><br><span class="muted"><?=e(($r['latitude']?:'').' '.($r['longitude']?:''))?></span></td><td><?=e($r['business_count'])?></td><td><?=$r['status']?'Active':'Hidden'?></td><td><a class="btn ghost" href="?edit=<?=e($r['id'])?>">Edit</a></td></tr><?php endforeach;?></table></div></div>
<script>function geo(){const s=document.getElementById('geoStatus');if(!navigator.geolocation){s.textContent='Not supported';return}s.textContent=' Getting location...';navigator.geolocation.getCurrentPosition(p=>{document.getElementById('lat').value=p.coords.latitude.toFixed(7);document.getElementById('lng').value=p.coords.longitude.toFixed(7);s.textContent=' Location captured.'},e=>s.textContent=' '+e.message,{enableHighAccuracy:true,timeout:10000})}</script>
<?php require __DIR__.'/../app/end.php';?>
